-- Preserve the existing landing FAQ on initial migration only.
update public.site_settings set data=jsonb_set(data,'{faq}','[{"question": "Tôi có thể dùng SmartTeach miễn phí không?", "answer": "Có. Quiz, trò chơi cơ bản và tiện ích lớp học vẫn miễn phí. Premium mở khóa soạn và giao đề online với giá 50.000đ/tháng hoặc 500.000đ/năm, không tự động gia hạn."}, {"question": "Học sinh có cần tạo tài khoản để chơi quiz không?", "answer": "Không. Học sinh chỉ cần mã PIN do giáo viên cung cấp để tham gia."}, {"question": "Tôi có thể sử dụng lại câu hỏi và lớp học không?", "answer": "Có. Quiz và danh sách lớp đã lưu có thể được mở lại cho những buổi học tiếp theo."}, {"question": "SmartTeach có dùng được trên điện thoại không?", "answer": "Có. Giao diện hoạt động trên điện thoại, máy tính bảng và máy tính."}]'::jsonb) where version=1 and data->'faq'='[]'::jsonb;
